{
  "files": {
    "registration.php": "<?php\ndeclare(strict_types=1);\n\nuse Magento\\Framework\\Component\\ComponentRegistrar;\n\nComponentRegistrar::register(\n    ComponentRegistrar::MODULE,\n    'Vendor_ImageTagging',\n    __DIR__\n);",
    "etc/module.xml": "<?xml version=\"1.0\"?>\n<config xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n        xsi:noNamespaceSchemaLocation=\"urn:magento:framework:Module/etc/module.xsd\">\n    <module name=\"Vendor_ImageTagging\">\n        <sequence>\n            <module name=\"Magento_Catalog\"/>\n            <module name=\"Magento_Eav\"/>\n            <module name=\"Magento_Backend\"/>\n            <module name=\"Magento_AsynchronousOperations\"/>\n        </sequence>\n    </module>\n</config>",
    "etc/di.xml": "<?xml version=\"1.0\"?>\n<config xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n        xsi:noNamespaceSchemaLocation=\"urn:magento:framework:ObjectManager/etc/config.xsd\">\n    \n    <!-- Plugin to intercept product image save -->\n    <type name=\"Magento\\Catalog\\Model\\Product\\Gallery\\Processor\">\n        <plugin name=\"vendor_imagetagging_analyze_on_upload\"\n                type=\"Vendor\\ImageTagging\\Plugin\\Product\\Gallery\\ProcessorPlugin\"\n                sortOrder=\"10\"/>\n    </type>\n    \n    <!-- Plugin for mass action -->\n    <type name=\"Magento\\Catalog\\Model\\Product\\Action\">\n        <plugin name=\"vendor_imagetagging_mass_action\"\n                type=\"Vendor\\ImageTagging\\Plugin\\Product\\MassActionPlugin\"\n                sortOrder=\"10\"/>\n    </type>\n    \n    <!-- Service contracts -->\n    <preference for=\"Vendor\\ImageTagging\\Api\\ImageAnalysisServiceInterface\"\n                type=\"Vendor\\ImageTagging\\Model\\ImageAnalysisService\"/>\n    <preference for=\"Vendor\\ImageTagging\\Api\\AttributeTaggingServiceInterface\"\n                type=\"Vendor\\ImageTagging\\Model\\AttributeTaggingService\"/>\n    <preference for=\"Vendor\\ImageTagging\\Api\\Data\\TagSuggestionInterface\"\n                type=\"Vendor\\ImageTagging\\Model\\Data\\TagSuggestion\"/>\n    <preference for=\"Vendor\\ImageTagging\\Api\\TagSuggestionRepositoryInterface\"\n                type=\"Vendor\\ImageTagging\\Model\\TagSuggestionRepository\"/>\n    \n    <!-- Virtual types for async operations -->\n    <virtualType name=\"Vendor\\ImageTagging\\Model\\BulkImageAnalysis\"\n                 type=\"Magento\\AsynchronousOperations\\Model\\MassSchedule\">\n        <arguments>\n            <argument name=\"consumer\" xsi:type=\"string\">imageTagging.bulkAnalysis</argument>\n        </arguments>\n    </virtualType>\n    \n</config>",
    "etc/events.xml": "<?xml version=\"1.0\"?>\n<config xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n        xsi:noNamespaceSchemaLocation=\"urn:magento:framework:Event/etc/events.xsd\">\n    \n    <!-- Observer for attribute application -->\n    <event name=\"catalog_product_attribute_update_before\">\n        <observer name=\"vendor_imagetagging_validate_confidence\"\n                  instance=\"Vendor\\ImageTagging\\Observer\\ValidateConfidenceThreshold\"/>\n    </event>\n    \n    <!-- Observer for reindex trigger -->\n    <event name=\"vendor_imagetagging_attributes_applied\">\n        <observer name=\"vendor_imagetagging_trigger_reindex\"\n                  instance=\"Vendor\\ImageTagging\\Observer\\TriggerPartialReindex\"/>\n    </event>\n    \n</config>",
    "etc/adminhtml/system.xml": "<?xml version=\"1.0\"?>\n<config xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n        xsi:noNamespaceSchemaLocation=\"urn:magento:module:Magento_Config:etc/system_file.xsd\">\n    <system>\n        <tab id=\"catalog\" translate=\"label\" sortOrder=\"200\">\n            <label>Catalog</label>\n        </tab>\n        <section id=\"imagetagging\" translate=\"label\" sortOrder=\"400\" showInDefault=\"1\" showInWebsite=\"1\" showInStore=\"1\">\n            <label>Product Image Tagging</label>\n            <tab>catalog</tab>\n            <resource>Vendor_ImageTagging::config</resource>\n            <group id=\"general\" translate=\"label\" sortOrder=\"10\" showInDefault=\"1\" showInWebsite=\"1\" showInStore=\"1\">\n                <label>General Settings</label>\n                <field id=\"enabled\" translate=\"label\" type=\"select\" sortOrder=\"10\" showInDefault=\"1\" showInWebsite=\"1\" showInStore=\"1\">\n                    <label>Enable Image Tagging</label>\n                    <source_model>Magento\\Config\\Model\\Config\\Source\\Yesno</source_model>\n                </field>\n                <field id=\"auto_apply\" translate=\"label comment\" type=\"select\" sortOrder=\"20\" showInDefault=\"1\" showInWebsite=\"1\" showInStore=\"1\">\n                    <label>Auto-Apply High Confidence Tags</label>\n                    <source_model>Magento\\Config\\Model\\Config\\Source\\Yesno</source_model>\n                    <comment>Automatically apply tags with confidence above threshold</comment>\n                </field>\n                <field id=\"confidence_threshold\" translate=\"label comment\" type=\"text\" sortOrder=\"30\" showInDefault=\"1\" showInWebsite=\"1\" showInStore=\"1\">\n                    <label>Confidence Threshold (%)</label>\n                    <validate>validate-number validate-number-range number-range-0-100</validate>\n                    <comment>Minimum confidence score (0-100) to consider a tag suggestion</comment>\n                </field>\n            </group>\n            <group id=\"ai_service\" translate=\"label\" sortOrder=\"20\" showInDefault=\"1\" showInWebsite=\"0\" showInStore=\"0\">\n                <label>AI Service Configuration</label>\n                <field id=\"provider\" translate=\"label\" type=\"select\" sortOrder=\"10\" showInDefault=\"1\">\n                    <label>AI Provider</label>\n                    <source_model>Vendor\\ImageTagging\\Model\\Config\\Source\\AiProvider</source_model>\n                </field>\n                <field id=\"api_key\" translate=\"label\" type=\"obscure\" sortOrder=\"20\" showInDefault=\"1\">\n                    <label>API Key</label>\n                    <backend_model>Magento\\Config\\Model\\Config\\Backend\\Encrypted</backend_model>\n                </field>\n                <field id=\"api_endpoint\" translate=\"label\" type=\"text\" sortOrder=\"30\" showInDefault=\"1\">\n                    <label>API Endpoint URL</label>\n                    <validate>validate-url</validate>\n                </field>\n            </group>\n            <group id=\"attribute_mapping\" translate=\"label\" sortOrder=\"30\" showInDefault=\"1\" showInWebsite=\"1\" showInStore=\"1\">\n                <label>Attribute Mapping Rules</label>\n                <field id=\"color_attribute\" translate=\"label\" type=\"select\" sortOrder=\"10\" showInDefault=\"1\" showInWebsite=\"1\" showInStore=\"1\">\n                    <label>Color Attribute Code</label>\n                    <source_model>Vendor\\ImageTagging\\Model\\Config\\Source\\ProductAttributes</source_model>\n                </field>\n                <field id=\"material_attribute\" translate=\"label\" type=\"select\" sortOrder=\"20\" showInDefault=\"1\" showInWebsite=\"1\" showInStore=\"1\">\n                    <label>Material Attribute Code</label>\n                    <source_model>Vendor\\ImageTagging\\Model\\Config\\Source\\ProductAttributes</source_model>\n                </field>\n                <field id=\"style_attribute\" translate=\"label\" type=\"select\" sortOrder=\"30\" showInDefault=\"1\" showInWebsite=\"1\" showInStore=\"1\">\n                    <label>Style Attribute Code</label>\n                    <source_model>Vendor\\ImageTagging\\Model\\Config\\Source\\ProductAttributes</source_model>\n                </field>\n            </group>\n        </section>\n    </system>\n</config>",
    "etc/db_schema.xml": "<?xml version=\"1.0\"?>\n<schema xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n        xsi:noNamespaceSchemaLocation=\"urn:magento:framework:Setup/Declaration/Schema/etc/schema.xsd\">\n    \n    <table name=\"vendor_imagetagging_suggestion\" resource=\"default\" engine=\"innodb\" comment=\"Image Tag Suggestions\">\n        <column xsi:type=\"int\" name=\"suggestion_id\" unsigned=\"true\" nullable=\"false\" identity=\"true\" comment=\"Suggestion ID\"/>\n        <column xsi:type=\"int\" name=\"product_id\" unsigned=\"true\" nullable=\"false\" comment=\"Product ID\"/>\n        <column xsi:type=\"varchar\" name=\"image_path\" nullable=\"false\" length=\"255\" comment=\"Image Path\"/>\n        <column xsi:type=\"varchar\" name=\"attribute_code\" nullable=\"false\" length=\"255\" comment=\"Attribute Code\"/>\n        <column xsi:type=\"text\" name=\"suggested_value\" nullable=\"false\" comment=\"Suggested Value\"/>\n        <column xsi:type=\"decimal\" name=\"confidence_score\" scale=\"4\" precision=\"10\" unsigned=\"false\" nullable=\"false\" comment=\"Confidence Score\"/>\n        <column xsi:type=\"varchar\" name=\"status\" nullable=\"false\" length=\"50\" default=\"pending\" comment=\"Status: pending, applied, rejected\"/>\n        <column xsi:type=\"int\" name=\"applied_by\" unsigned=\"true\" nullable=\"true\" comment=\"Admin User ID\"/>\n        <column xsi:type=\"timestamp\" name=\"created_at\" on_update=\"false\" nullable=\"false\" default=\"CURRENT_TIMESTAMP\" comment=\"Created At\"/>\n        <column xsi:type=\"timestamp\" name=\"updated_at\" on_update=\"true\" nullable=\"false\" default=\"CURRENT_TIMESTAMP\" comment=\"Updated At\"/>\n        \n        <constraint xsi:type=\"primary\" referenceId=\"PRIMARY\">\n            <column name=\"suggestion_id\"/>\n        </constraint>\n        \n        <constraint xsi:type=\"foreign\" referenceId=\"VENDOR_IMAGETAGGING_SUGGESTION_PRODUCT_ID\"\n                    table=\"vendor_imagetagging_suggestion\" column=\"product_id\"\n                    referenceTable=\"catalog_product_entity\" referenceColumn=\"entity_id\" onDelete=\"CASCADE\"/>\n        \n        <constraint xsi:type=\"foreign\" referenceId=\"VENDOR_IMAGETAGGING_SUGGESTION_APPLIED_BY\"\n                    table=\"vendor_imagetagging_suggestion\" column=\"applied_by\"\n                    referenceTable=\"admin_user\" referenceColumn=\"user_id\" onDelete=\"SET NULL\"/>\n        \n        <index referenceId=\"VENDOR_IMAGETAGGING_SUGGESTION_PRODUCT_ID\" indexType=\"btree\">\n            <column name=\"product_id\"/>\n        </index>\n        \n        <index referenceId=\"VENDOR_IMAGETAGGING_SUGGESTION_STATUS\" indexType=\"btree\">\n            <column name=\"status\"/>\n        </index>\n    </table>\n    \n    <table name=\"vendor_imagetagging_batch_report\" resource=\"default\" engine=\"innodb\" comment=\"Batch Processing Reports\">\n        <column xsi:type=\"int\" name=\"report_id\" unsigned=\"true\" nullable=\"false\" identity=\"true\" comment=\"Report ID\"/>\n        <column xsi:type=\"varchar\" name=\"bulk_uuid\" nullable=\"false\" length=\"40\" comment=\"Bulk Operation UUID\"/>\n        <column xsi:type=\"int\" name=\"total_products\" unsigned=\"true\" nullable=\"false\" default=\"0\" comment=\"Total Products\"/>\n        <column xsi:type=\"int\" name=\"success_count\" unsigned=\"true\" nullable=\"false\" default=\"0\" comment=\"Success Count\"/>\n        <column xsi:type=\"int\" name=\"failure_count\" unsigned=\"true\" nullable=\"false\" default=\"0\" comment=\"Failure Count\"/>\n        <column xsi:type=\"text\" name=\"error_details\" nullable=\"true\" comment=\"Error Details JSON\"/>\n        <column xsi:type=\"timestamp\" name=\"started_at\" on_update=\"false\" nullable=\"false\" default=\"CURRENT_TIMESTAMP\" comment=\"Started At\"/>\n        <column xsi:type=\"timestamp\" name=\"completed_at\" on_update=\"false\" nullable=\"true\" comment=\"Completed At\"/>\n        \n        <constraint xsi:type=\"primary\" referenceId=\"PRIMARY\">\n            <column name=\"report_id\"/>\n        </constraint>\n        \n        <constraint xsi:type=\"unique\" referenceId=\"VENDOR_IMAGETAGGING_BATCH_REPORT_BULK_UUID\">\n            <column name=\"bulk_uuid\"/>\n        </constraint>\n    </table>\n    \n</schema>",
    "Api/ImageAnalysisServiceInterface.php": "<?php\ndeclare(strict_types=1);\n\nnamespace Vendor\\ImageTagging\\Api;\n\nuse Vendor\\ImageTagging\\Api\\Data\\TagSuggestionInterface;\n\n/**\n * Image Analysis Service Interface\n *\n * @api\n */\ninterface ImageAnalysisServiceInterface\n{\n    /**\n     * Analyze product image and generate tag suggestions\n     *\n     * @param int $productId\n     * @param string $imagePath\n     * @return TagSuggestionInterface[]\n     * @throws \\Magento\\Framework\\Exception\\LocalizedException\n     */\n    public function analyzeImage(int $productId, string $imagePath): array;\n\n    /**\n     * Analyze multiple product images in batch\n     *\n     * @param int[] $productIds\n     * @return array<int, TagSuggestionInterface[]> Product ID => Suggestions\n     * @throws \\Magento\\Framework\\Exception\\LocalizedException\n     */\n    public function analyzeBatch(array $productIds): array;\n\n    /**\n     * Test AI service connection\n     *\n     * @return bool\n     */\n    public function testConnection(): bool;\n}",
    "Api/AttributeTaggingServiceInterface.php": "<?php\ndeclare(strict_types=1);\n\nnamespace Vendor\\ImageTagging\\Api;\n\nuse Vendor\\ImageTagging\\Api\\Data\\TagSuggestionInterface;\n\n/**\n * Attribute Tagging Service Interface\n *\n * @api\n */\ninterface AttributeTaggingServiceInterface\n{\n    /**\n     * Apply tag suggestions to product attributes\n     *\n     * @param int $productId\n     * @param int[] $suggestionIds\n     * @param int $adminUserId\n     * @return bool\n     * @throws \\Magento\\Framework\\Exception\\LocalizedException\n     */\n    public function applyTags(int $productId, array $suggestionIds, int $adminUserId): bool;\n\n    /**\n     * Get pending suggestions for product\n     *\n     * @param int $productId\n     * @return TagSuggestionInterface[]\n     */\n    public function getPendingSuggestions(int $productId): array;\n\n    /**\n     * Reject tag suggestions\n     *\n     * @param int[] $suggestionIds\n     * @param int $adminUserId\n     * @return bool\n     */\n    public function